  /// ([seconds] before the end: where the outro starts). INFERRED shape: the original's call was not recovered; it has
  /// the buttons (seen in 1.1.7) and keeps the marks in video_head_tail.json.
  func onHeadTailMarked(sessionId sessionIdArg: String, type typeArg: String, seconds secondsArg: Double, completion: @escaping (Result<Void, PigeonError>) -> Void) {
    let channelName: String = "dev.flutter.pigeon.uzv_reimpl.NativePlayerFlutterApi.onHeadTailMarked\(messageChannelSuffix)"
    let channel = FlutterBasicMessageChannel(name: channelName, binaryMessenger: binaryMessenger, codec: codec)
    channel.sendMessage([sessionIdArg, typeArg, secondsArg] as [Any?]) { response in
      guard let listResponse = response as? [Any?] else {
        completion(.failure(createConnectionError(withChannelName: channelName)))
        return
      }
      if listResponse.count > 1 {
        let code: String = listResponse[0] as! String
        let message: String? = nilOrValue(listResponse[1])
        let details: String? = nilOrValue(listResponse[2])
        completion(.failure(PigeonError(code: code, message: message, details: details)))
      } else {
        completion(.success(Void()))
      }
    }
  }
}
